const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Monte Pisano region, Northern Italy
  const montePisano = ee.Geometry.Point([10.4, 43.7]).buffer(5000); // ~5km buffer

  // Define date range: Feb 24-26, 2019
  const startDate = '2019-02-24';
  const endDate = '2019-02-27';

  // Load MODIS Thermal Anomalies dataset
  const modisTA = ee.ImageCollection('MODIS/006/MOD14A1')
    .filterDate(startDate, endDate)
    .filterBounds(montePisano);

  const size = modisTA.size().getInfo();
  console.log(`MODIS Thermal Anomalies images found: ${size}`);

  if (size === 0) {
    console.log('No MODIS data available for this date range.');
    console.log('C1');
    return;
  }

  // Process each image and check for fire detections
  // Fire mask: 1 = fire detected, confidence > 0
  const fireDetected = modisTA.map(function(img) {
    const fireMask = img.select('FireMask');
    const confidence = img.select('MaxFRP'); // Maximum Fire Radiative Power
    return img.set('firePixels', fireMask.eq(1).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: montePisano,
      scale: 1000,
      maxPixels: 1e9
    }).get('FireMask'));
  });

  const results = fireDetected.aggregate_array('firePixels').getInfo();
  console.log(`Fire pixels per image: ${results}`);

  // Check if any fire pixels detected
  const totalFirePixels = results.reduce((a, b) => a + (b || 0), 0);
  console.log(`Total fire pixels detected: ${totalFirePixels}`);

  // Also get high confidence fire detections
  const confidenceCheck = modisTA.select('MaxFRP')
    .reduce(ee.Reducer.max())
    .reduceRegion({
      reducer: ee.Reducer.first(),
      geometry: montePisano,
      scale: 1000,
      maxPixels: 1e9
    }).getInfo();

  console.log(`Max Fire Radiative Power detected: ${confidenceCheck}`);

  if (totalFirePixels > 0 || (confidenceCheck && confidenceCheck.MaxFRP > 0)) {
    console.log('Active fire detected in Monte Pisano (Feb 24-26, 2019)');
    console.log('A');
  } else {
    console.log('No active fire detected in Monte Pisano (Feb 24-26, 2019)');
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
